package com.wylie.registration.closing;

import com.wylie.registration.registration.Rules;
import org.junit.jupiter.api.Test;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class LevelingTest {
    private final Map<String,Object> term=Map.of("startDate","2026-09-01","endDate","2026-12-31");
    private Map<String,Object> offering(long id,boolean teacher){var m=new HashMap<String,Object>();m.put("id",id);m.put("courseId",id);m.put("meetings",List.of());if(teacher)m.put("professorId",1);return m;}
    private Leveling.Participant person(long id,Set<Long> active,long... alternatives){var choices=new ArrayList<Leveling.Choice>();int p=0;for(long course:new TreeSet<>(active))choices.add(new Leveling.Choice(course,"PRIMARY",++p));int a=0;for(long course:alternatives)choices.add(new Leveling.Choice(course,"ALTERNATE",++a));return new Leveling.Participant(id,Instant.parse("2026-10-07T01:00:00Z"),choices,active);}
    @Test void lowClassCanReachThreeBeforeCancellation(){var people=List.of(person(1,Set.of(),4),person(2,Set.of(4L)),person(3,Set.of(4L)));var plan=Leveling.calculate(people,List.of(offering(4,true)),term,(s,o)->true);assertEquals("CONFIRMED",plan.states().get(4L));assertTrue(plan.courses().get(1L).contains(4L));assertEquals("ALTERNATE",plan.origins().get(1L).get(4L));}
    @Test void failedCandidateDoesNotRemoveExistingSeat(){var people=List.of(person(1,Set.of(1L,2L,3L,4L),5),person(2,Set.of(1L,2L,3L)),person(3,Set.of(1L,2L,3L)));var plan=Leveling.calculate(people,List.of(offering(1,true),offering(2,true),offering(3,true),offering(4,true),offering(5,true)),term,(s,o)->false);assertEquals(Set.of(1L,2L,3L),plan.courses().get(1L));assertEquals("LOW_ENROLLMENT",plan.reasons().get(1L).get(4L));assertFalse(plan.reasons().get(1L).containsValue("REPLACED_BY_ALTERNATE"));}
    @Test void replacementUsesLargestUnconfirmedPrimaryOrder(){var people=new ArrayList<Leveling.Participant>();people.add(person(1,Set.of(1L,2L,3L,4L),5));people.add(person(2,Set.of(1L,2L,3L,5L)));people.add(person(3,Set.of(1L,2L,3L,5L)));var offers=List.of(offering(1,true),offering(2,true),offering(3,true),offering(4,true),offering(5,true));var plan=Leveling.calculate(people,offers,term,(s,o)->true);assertEquals(Set.of(1L,2L,3L,5L),plan.courses().get(1L));assertEquals("REPLACED_BY_ALTERNATE",plan.reasons().get(1L).get(4L));}
    @Test void noInstructorAlwaysCancels(){var people=List.of(person(1,Set.of(1L)),person(2,Set.of(1L)),person(3,Set.of(1L)));var plan=Leveling.calculate(people,List.of(offering(1,false)),term,(s,o)->true);assertEquals("CANCELLED",plan.states().get(1L));assertTrue(plan.courses().values().stream().allMatch(Set::isEmpty));}
    @Test void firstTimeThenStudentIdDecidesLastSeat(){var people=new ArrayList<Leveling.Participant>();for(int i=1;i<=9;i++)people.add(person(i,Set.of(1L)));people.add(person(20,Set.of(),1));people.add(person(10,Set.of(),1));var plan=Leveling.calculate(people,List.of(offering(1,true)),term,(s,o)->true);assertTrue(plan.courses().get(10L).contains(1L));assertTrue(plan.courses().get(20L).isEmpty());assertEquals(10,plan.courses().values().stream().filter(s->s.contains(1L)).count());}
    @Test void permutationsProduceSameSortedResult(){var input=new ArrayList<Leveling.Participant>();for(int i=1;i<=15;i++)input.add(person(i,Set.of(),1,2));var offers=List.of(offering(1,true),offering(2,true));var expected=Leveling.calculate(input,offers,term,(s,o)->true).courses();for(int i=0;i<100;i++){Collections.shuffle(input,new Random(i));assertEquals(expected,Leveling.calculate(input,offers,term,(s,o)->true).courses());}}
    @Test void adjacentAndDifferentTeachingWeeksDoNotConflict(){Map<String,Object> a=Map.of("weekday",1,"startTime","08:00:00","endTime","09:00:00","firstDate","2026-09-01","lastDate","2026-12-31");var b=new HashMap<>(a);b.put("startTime","09:00:00");b.put("endTime","10:00:00");assertFalse(Rules.conflict(Map.of("meetings",List.of(a)),Map.of("meetings",List.of(b)),term));b.put("startTime","08:30:00");assertTrue(Rules.conflict(Map.of("meetings",List.of(a)),Map.of("meetings",List.of(b)),term));var odd=new HashMap<>(a);odd.put("weekMask","101010101010101010");var even=new HashMap<>(a);even.put("weekMask","010101010101010101");assertFalse(Rules.conflict(Map.of("meetings",List.of(odd)),Map.of("meetings",List.of(even)),term));}
}
